<?php
use App\Repositories\LeadIntakeRepository;use App\Services\LoginService;use App\Services\ManagerAvailabilityService;use App\Utils\Router;use App\Utils\TemplateResponse;use App\Utils\UserContext;use App\Utils\LocationUtils;use App\Utils\MessageUtil;
$router=new Router();
$router->get(function(){$owner=LoginService::getSession()->getOwner();return TemplateResponse::render(__DIR__.'/index.twig',[...UserContext::get(),'leads'=>(new LeadIntakeRepository())->all($owner)]);});
$router->post(function(){$owner=LoginService::getSession()->getOwner();$id=(int)($_POST['id']??0);$repo=new LeadIntakeRepository();$lead=$repo->find($owner,$id);if(!$lead){MessageUtil::setMessage('Lead Intake not found.');LocationUtils::redirectInternal('panel/lead-intake');}$engine=new ManagerAvailabilityService();$result=$engine->evaluate($owner,$lead->event_date,$lead->start_time,$lead->end_time,(int)$lead->setup_minutes);$engine->record($owner,'LEAD_INTAKE',$id,$result,$result['suggested_manager_id']??null,LoginService::getSession()->getId());$repo->update($owner,$id,['availability_status'=>$result['status'],'suggested_manager_id'=>$result['suggested_manager_id']??null,'availability_checked_at'=>date('Y-m-d H:i:s'),'status'=>$result['status']===ManagerAvailabilityService::AVAILABLE?'QUALIFIED':'NEEDS_REVIEW']);MessageUtil::setMessage($result['message'],$result['status']==='AVAILABLE'?'Available':'Scheduling review','info');LocationUtils::redirectInternal('panel/lead-intake');});$router->run();
